import Foundation
import Dispatch

// MARK: - Role-Based Access Control
enum Role: Int, Comparable {
    case viewer = 0
    case operator_ = 1
    case admin = 2

    static func < (lhs: Role, rhs: Role) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

struct User {
    let id: String
    let username: String
    var role: Role
}

// MARK: - Log Entry
struct LogEntry {
    let timestamp: Date
    let level: String
    let message: String
    let source: String
    let sensitivityLevel: Role  // minimum role to view this entry
}

// MARK: - Monitoring Agent
class MonitoringAgent {
    private var logBuffer: [LogEntry] = []
    private let bufferQueue = DispatchQueue(label: "com.agent.buffer", attributes: .concurrent)
    private var sessionCache: [String: User] = [:]
    private let sessionQueue = DispatchQueue(label: "com.agent.session", attributes: .concurrent)
    private let flushThreshold = 100

    // Register a user session
    func registerSession(user: User) {
        sessionQueue.async(flags: .barrier) {
            self.sessionCache[user.id] = user
        }
    }

    // Update user role (e.g., admin demotes a user)
    func updateUserRole(userId: String, newRole: Role, requestedBy: User) {
        guard requestedBy.role == .admin else { return }
        sessionQueue.async(flags: .barrier) {
            self.sessionCache[userId]?.role = newRole
        }
    }

    // Ingest a log entry into the buffer
    func ingest(entry: LogEntry) {
        bufferQueue.async(flags: .barrier) {
            self.logBuffer.append(entry)
            if self.logBuffer.count >= self.flushThreshold {
                self.flushBuffer()
            }
        }
    }

    // Query logs - checks RBAC
    func queryLogs(userId: String, filter: String?, completion: @escaping ([LogEntry]) -> Void) {
        // Step 1: Snapshot the user's role
        var capturedUser: User?
        sessionQueue.sync {
            capturedUser = self.sessionCache[userId]
        }

        guard let user = capturedUser else {
            completion([])
            return
        }

        // Step 2: Perform filtering on concurrent queue (potentially delayed)
        bufferQueue.async {
            // Re-read role at filter time to get "latest" permissions
            // This is the intended security enhancement for real-time role changes
            var currentRole: Role = user.role
            self.sessionQueue.sync {
                if let updatedUser = self.sessionCache[userId] {
                    currentRole = updatedUser.role
                }
            }

            let filtered = self.logBuffer.filter { entry in
                let roleCheck = currentRole >= entry.sensitivityLevel
                let filterCheck: Bool
                if let f = filter {
                    filterCheck = entry.message.contains(f) || entry.source.contains(f)
                } else {
                    filterCheck = true
                }
                return roleCheck && filterCheck
            }
            completion(filtered)
        }
    }

    // Flush buffer to persistent storage
    private func flushBuffer() {
        // In production, this would write to disk/network
        let snapshot = self.logBuffer
        self.logBuffer.removeAll(keepingCapacity: true)
        DispatchQueue.global().async {
            // Simulate I/O latency
            Thread.sleep(forTimeInterval: 0.01)
            print("Flushed \(snapshot.count) entries to storage")
        }
    }

    // Admin-only: export all logs including sensitive entries
    func exportAllLogs(requestedBy userId: String, completion: @escaping ([LogEntry]?) -> Void) {
        sessionQueue.sync {
            guard let user = self.sessionCache[userId], user.role == .admin else {
                completion(nil)
                return
            }
        }
        bufferQueue.sync {
            completion(self.logBuffer)
        }
    }

    // Get agent status - available to all authenticated users
    func getStatus(userId: String) -> [String: Any]? {
        var user: User?
        sessionQueue.sync {
            user = self.sessionCache[userId]
        }
        guard user != nil else { return nil }

        var count = 0
        bufferQueue.sync {
            count = self.logBuffer.count
        }
        return ["bufferSize": count, "threshold": flushThreshold]
    }
}

// MARK: - Agent Singleton
let sharedAgent = MonitoringAgent()
